ILSMARC ; m-ils MARCXML loader — MARC21 slim XML to tagged-line records
 ; Ingests the fleet's staged NLM files (serfilebase/catplusbase, gzip-
 ; expanded beforehand) into the tagged-line internal format via ILSREC.
 ; The slim schema is regular: <marc:record> blocks contain
 ;   <marc:controlfield tag="001">0402304</marc:controlfield>
 ;   <marc:datafield tag="650" ind1=" " ind2="2">
 ;     <marc:subfield code="a">Diabetes Mellitus</marc:subfield>
 ; MARC to internal tag map (first subfield $a per datafield):
 ;   001 -> ID (controlfield)   245 -> BTI (CAT) / STI (SER)
 ;   022 -> ISS                 260 -> PB ($b) , DP ($c)
 ;   100/700 -> AU              650 -> MH (repeatable; ind2=2 = MeSH)
 ; Pure-string M parsing, $P-piece based; bounded loops only (no
 ; QUIT-in-FOR, one command per IF); runs under mJVM and GT.M.
 ;
LOADFILE(kind,fn) ; stream a MARCXML file into the store (DO form). The
 ; record count lands in ^ILS("TMP","ING") — GT.M forbids Q with argument
 ; in a DOed label, and mJVM #37 dies silently with device ops inside an
 ; extrinsic frame; top-level-style device loops are proven on both engines.
 ; One <marc:record> block per run of lines, no blank lines (NLM slim output
 ; meets both); EOF reads as "". No WRITEs inside the loop — the current
 ; device stays the file until CLOSE returns to the principal.
 N line,rec,n,r
 S n=0
 S rec=""
 O 20:fn
 U 20
LF1 ;
 R line
 I line="" G LFD
 I rec="" D LF2
 I rec'="" D LF3
 G LF1
LF2 ;
 I line'["<marc:record " Q
 S rec=line
 Q
 ;
LF3 ;
 S rec=rec_$C(10)_line
 I line'["</marc:record>" Q
 S r=$$LOADXML(kind,rec)
 I r>0 S n=(n)+1
 S rec=""
 Q
 ;
LFD ;
 C 20
 U 0
 S ^ILS("TMP","ING")=n
 Q
 ;
LOADXML(kind,text) ; parse one <marc:record> body; returns field count
 N recid,chunk,attrs,tag,body,cnt,tot
 S chunk=$P(text,"<marc:controlfield tag=""001"">",2)
 I chunk="" Q 0
 S recid=$P(chunk,"</marc:controlfield>",1)
 I recid="" Q 0
 D PUT(recid,kind,"ID",1,recid)
 S tot=$L(text,"<marc:datafield ")-1
 F cnt=1:1:tot D
 . S chunk=$P(text,"<marc:datafield ",2)
 . S attrs=$P(chunk,">",1)
 . S tag=$P(attrs,"""",2)
 . S body=$P(chunk,">",2,999)
 . S body=$P(body,"</marc:datafield>",1)
 . D FIELD(kind,recid,tag,body)
 . S text=$P(text,"</marc:datafield>",2,999)
 Q (tot+1)
 ;
FIELD(kind,recid,tag,body) ; map one datafield to internal tags
 I tag="245" D S245 Q
 I tag="022" D S022 Q
 I tag="260" D S260 Q
 I tag="264" D S260 Q
 I tag="100" D SAU Q
 I tag="700" D SAU Q
 I tag="650" D SMH Q
 Q
 ;
SUBA(body) ; first $a subfield value of a datafield body ("" when absent)
 N sub,val
 S sub=$P(body,"<marc:subfield ",2,999)
 I sub="" Q ""
 S val=$P(sub,">",2,999)
 S val=$P(val,"</marc:subfield>",1)
 Q val
 ;
S245 ; title
 I kind="CAT" D PUT(recid,kind,"BTI",1,$$SUBA(body)) Q
 D PUT(recid,kind,"STI",1,$$SUBA(body))
 Q
 ;
S022 ; ISSN
 D PUT(recid,kind,"ISS",1,$$SUBA(body))
 Q
 ;
S260 ; publication: $b publisher, $c date
 D PUT(recid,kind,"PB",1,$$SUBB(body))
 D PUT(recid,kind,"DP",1,$$SUBC(body))
 Q
 ;
SUBB(body) ; first $b subfield value
 N sub,val
 S sub=$P(body,"<marc:subfield ",2,999)
 I sub="" Q ""
 S val=$P(sub,"code=""b""",2,999)
 I val="" Q ""
 S val=$P(val,">",2,999)
 S val=$P(val,"</marc:subfield>",1)
 Q val
 ;
SUBC(body) ; first $c subfield value
 N sub,val
 S sub=$P(body,"<marc:subfield ",2,999)
 I sub="" Q ""
 S val=$P(sub,"code=""c""",2,999)
 I val="" Q ""
 S val=$P(val,">",2,999)
 S val=$P(val,"</marc:subfield>",1)
 Q val
 ;
SAU ; author
 I $$SUBA(body)="" Q
 D SEQPUT(recid,kind,"AU",$$SUBA(body))
 Q
 ;
SMH ; MeSH heading (650 ind2=2 in NLM data)
 I $$SUBA(body)="" Q
 D SEQPUT(recid,kind,"MH",$$SUBA(body))
 Q
 ;
COUNTREC(text) ; how many <marc:record> blocks in a collection
 Q ($L(text,"<marc:record ")-1)
 ;
 ;
ILSMESH ; m-ils MeSH authority loader — NLM descYYYY.xml (DescriptorRecordSet)
 ; Streams the full MeSH descriptor file (31,110 records in desc2026) into
 ; the authority store via AUTHADD: ^ILS("AUTH",ui)=name,
 ; ^ILS("ATREE",ui)=first tree, ^ILS("ANAME",folded,ui), ^ILS("ATIX",tree,ui)
 ; (one entry per tree number). DO form — the count lands in
 ; ^ILS("TMP","MESH"). Record open tags carry attributes
 ; ("<DescriptorRecord DescriptorClass = ..."), no namespace prefixes.
 ; Names keep raw XML entities (&amp;) — the MARCXML 650 headings carry the
 ; same encoding, so VALIDATE lookups match without entity translation.
 ;
MESHFILE(fn) ; stream desc xml; count in ^ILS("TMP","MESH")
 N line,rec,n,r
 S n=0
 S rec=""
 O 20:fn
 U 20
MF1 ;
 R line
 I line="" G MFD
 I rec="" D MF2
 I rec'="" D MF3
 G MF1
 ;
MF2 ;
 I line'["<DescriptorRecord " Q
 S rec=line
 Q
 ;
MF3 ;
 S rec=rec_$C(10)_line
 I line'["</DescriptorRecord>" Q
 S r=$$MESHREC(rec)
 I r>0 S n=(n)+1
 S rec=""
 Q
 ;
MFD ;
 C 20
 U 0
 S ^ILS("TMP","MESH")=n
 Q
 ;
MESHREC(text) ; parse one DescriptorRecord block; returns 1 when stored
 N ui,name,rest,tree,t
 S ui=$P(text,"<DescriptorUI>",2)
 I ui="" Q 0
 S ui=$P(ui,"</DescriptorUI>",1)
 I ui="" Q 0
 S rest=$P(text,"<DescriptorName>",2,999)
 I rest="" Q 0
 S name=$P(rest,"<String>",2)
 I name="" Q 0
 S name=$P(name,"</String>",1)
 S tree=$P(text,"<TreeNumber>",2)
 I tree="" G MFNT
 S tree=$P(tree,"</TreeNumber>",1)
 D AUTHADD(ui,name,tree)
 S rest=text
MF4 ;
 I rest'["<TreeNumber>" G MF4D
 S rest=$P(rest,"<TreeNumber>",2,999)
 S t=$P(rest,"</TreeNumber>",1)
 I t'="" S ^ILS("ATIX",t,ui)=""
 G MF4
 ;
MF4D ;
 Q 1
 ;
MFNT ; no tree number: authority name index only
 S ^ILS("AUTH",ui)=name
 S ^ILS("ANAME",$$FOLD(name),ui)=""
 Q 1
